import java.io.ByteArrayInputStream
import java.util.UUID

private class TerminalBridge(private val receive:(String)->Unit){@JavascriptInterface fun postMessage(value:String){if(value.length<=32*1024)receive(value)}}
private class TerminalDisplay {var view:WebView?=null;var generation:String?=null;var sequence=0L;var ready=false}
@SuppressLint("SetJavaScriptEnabled")
@Composable
fun RovaiTerminalDialog(model:RovaiWorkspaceViewModel,boardId:String,nodeId:String,onClose:()->Unit){
    val context=LocalContext.current;val lifecycle=LocalLifecycleOwner.current.lifecycle;val phase by lifecycle.currentStateFlow.collectAsState();val scope=rememberCoroutineScope();val target=remember(boardId,nodeId){buildJsonObject{put("boardId",boardId);put("nodeId",nodeId)}}
    var snapshot by remember(target){mutableStateOf<JsonObject?>(null)};var error by remember(target){mutableStateOf<String?>(null)};var busy by remember{mutableStateOf(false)};var pending by remember(target){mutableStateOf<JsonObject?>(null)};var unknown by remember{mutableStateOf(false)}
    val display=remember(target){TerminalDisplay()};val inputs=remember(target){Channel<String>(64)};var revision by remember{mutableIntStateOf(0)}
    val html by produceState<String?>(null){value=withContext(Dispatchers.IO){val js=context.assets.open("rovai-terminal/xterm.js").bufferedReader().use{it.readText()}.replace("</script","<\\/script",ignoreCase=true);val css=context.assets.open("rovai-terminal/xterm.css").bufferedReader().use{it.readText()};"""<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none';script-src 'unsafe-inline';style-src 'unsafe-inline'"><style>$css html,body,#terminal{margin:0;width:100%;height:100%;overflow:hidden;background:#111;color:#ddd}</style><div id="terminal"></div><script>$js</script><script>const term=new Terminal({fontSize:13,cursorBlink:false,scrollback:2000,convertEol:false});term.open(document.getElementById('terminal'));window.rovaiReset=()=>term.reset();window.rovaiEnable=v=>term.options.disableStdin=!v;window.rovaiWrite=b=>{const data=atob(b);term.write(Uint8Array.from(data,c=>c.charCodeAt(0)))};term.onData(text=>{const bytes=new TextEncoder().encode(text);for(let i=0;i<bytes.length;i+=8192){let value='';for(const byte of bytes.slice(i,i+8192))value+=String.fromCharCode(byte);RovaiTerminal.postMessage(JSON.stringify({type:'input',bytesBase64:btoa(value)}))}});let last='';new ResizeObserver(()=>{const columns=Math.max(10,Math.min(500,Math.floor(innerWidth/8))),rows=Math.max(3,Math.min(200,Math.floor(innerHeight/17)));const key=columns+':'+rows;if(key!==last){last=key;term.resize(columns,rows);RovaiTerminal.postMessage(JSON.stringify({type:'resize',cols:columns,rows}))}}).observe(document.body);term.options.disableStdin=true;RovaiTerminal.postMessage(JSON.stringify({type:'ready'}));</script>"""}}
    suspend fun read(){val previous=snapshot;val params=buildJsonObject{put("target",target);put("generation",previous?.get("generation")?:JsonNull);put("afterSeq",if(display.generation==previous?.coreText("generation"))display.sequence else 0)};val next=model.query(RovaiOperation.CANVAS_TERMINALS_SNAPSHOT,params).coreObject();snapshot=next;val input=pending;if(input!=null){val receipt=next["inputs"].coreArray().firstOrNull{it.coreText("inputId")==input.coreText("inputId")};if(receipt?.coreText("status")=="written"){pending=null;unknown=false}else if(receipt?.coreText("status")=="not_written"){error="终端未写入这份输入，请核对后重试原输入。";unknown=true}};revision++}
    LaunchedEffect(target,phase){if(!phase.isAtLeast(Lifecycle.State.STARTED))return@LaunchedEffect;while(isActive){try{read()}catch(cancelled:CancellationException){throw cancelled}catch(failure:Exception){error=failure.message};delay(if(snapshot?.coreText("phase")=="running")500 else 2000)}}
    LaunchedEffect(target){for(bytes in inputs){while(pending!=null&&isActive)delay(30);val current=snapshot?:continue;val generation=current.coreText("generation");if(generation.isEmpty()||current.coreText("phase")!="running"){error="终端尚未运行，输入未发送。";continue};val request=buildJsonObject{put("target",target);put("generation",generation);put("inputId",UUID.randomUUID().toString());put("expectedInputSequence",current.coreLong("inputSequence"));put("bytesBase64",bytes)};pending=request;try{val result=model.query(RovaiOperation.CANVAS_TERMINALS_WRITE,request).coreObject();if(result.coreText("status")=="written"){snapshot=buildJsonObject{current.forEach{(key,value)->put(key,value)};put("inputSequence",result.coreLong("sequence"))};pending=null}else{read()}}catch(cancelled:CancellationException){throw cancelled}catch(failure:Exception){unknown=true;error=failure.message}}}
    fun action(operation:RovaiOperation,params:JsonObject){if(busy)return;scope.launch{busy=true;error=null;try{model.query(operation,params);read()}catch(cancelled:CancellationException){throw cancelled}catch(failure:Exception){error=failure.message}finally{busy=false}}}
    Dialog(onDismissRequest=onClose,properties=DialogProperties(usePlatformDefaultWidth=false)){Surface(Modifier.fillMaxSize()){Column(Modifier.fillMaxSize()){
        Row(Modifier.fillMaxWidth().padding(8.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){Text("终端 · ${snapshot?.coreText("phase")?:"正在读取"}",Modifier.weight(1f));TextButton(onClick=onClose){Text("关闭")}}
        error?.let{Text(it,color=MaterialTheme.colorScheme.error,modifier=Modifier.padding(8.dp))}
        Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){TextButton(enabled=!busy&&snapshot!=null&&(snapshot?.get("cleanupComplete") as? JsonPrimitive)?.booleanOrNull!=false,onClick={val current=snapshot?:return@TextButton;action(RovaiOperation.CANVAS_TERMINALS_START,buildJsonObject{put("target",target);put("coreGeneration",current.coreText("coreGeneration"));put("requestId",UUID.randomUUID().toString());put("expectedGeneration",current["generation"]?:JsonNull);put("cols",80);put("rows",24)})}){Text("启动")};TextButton(enabled=!busy&&!snapshot?.coreText("generation").isNullOrEmpty(),onClick={action(RovaiOperation.CANVAS_TERMINALS_STOP,buildJsonObject{put("target",target);put("generation",snapshot!!.coreText("generation"))})}){Text("停止")};if(unknown){TextButton(onClick={scope.launch{try{read()}catch(failure:Exception){error=failure.message}}}){Text("核对输入")};TextButton(onClick={pending?.let{action(RovaiOperation.CANVAS_TERMINALS_WRITE,it)}}){Text("重试原输入")}}}
        if(html!=null)AndroidView(modifier=Modifier.weight(1f).fillMaxWidth().imePadding(),factory={WebView(it).apply{display.view=this;settings.javaScriptEnabled=true;settings.allowFileAccess=false;settings.allowContentAccess=false;settings.domStorageEnabled=false;settings.setSupportMultipleWindows(false);settings.mixedContentMode=WebSettings.MIXED_CONTENT_NEVER_ALLOW;addJavascriptInterface(TerminalBridge{message->scope.launch{val value=runCatching{Json.parseToJsonElement(message).jsonObject}.getOrNull()?:return@launch;when(value.coreText("type")){"ready"->{display.ready=true;revision++};"input"->{if(!unknown&&inputs.trySend(value.coreText("bytesBase64")).isFailure)error="输入队列已满，请稍后继续。"};"resize"->{val current=snapshot;if(current?.coreText("phase")=="running")try{model.query(RovaiOperation.CANVAS_TERMINALS_RESIZE,buildJsonObject{put("target",target);put("generation",current.coreText("generation"));put("cols",value.coreLong("cols").coerceIn(1,1000));put("rows",value.coreLong("rows").coerceIn(1,1000))})}catch(failure:Exception){error=failure.message}}}}},"RovaiTerminal");webViewClient=object:WebViewClient(){override fun shouldOverrideUrlLoading(view:WebView?,request:WebResourceRequest?)=true;override fun shouldInterceptRequest(view:WebView?,request:WebResourceRequest?)=WebResourceResponse("text/plain","UTF-8",ByteArrayInputStream(ByteArray(0)))};loadDataWithBaseURL("https://rovai-terminal.invalid/",html!!,"text/html","UTF-8",null)}},update={view->val current=snapshot;if(display.ready&&current!=null){val generation=current.coreText("generation");if(display.generation!=generation||(current["gap"] as? JsonPrimitive)?.booleanOrNull==true){view.evaluateJavascript("window.rovaiReset()",null);display.sequence=0;display.generation=generation};current["chunks"].coreArray().forEach{chunk->val sequence=chunk.coreLong("seq");if(sequence>display.sequence){val encoded=JsonPrimitive(chunk.coreText("bytesBase64")).toString();view.evaluateJavascript("window.rovaiWrite($encoded)",null);display.sequence=sequence}};val enabled=current.coreText("phase")=="running"&&!unknown&&phase.isAtLeast(Lifecycle.State.STARTED);view.evaluateJavascript("window.rovaiEnable($enabled)",null)}})
        Text("关闭界面会保留终端进程；需要结束时点击停止。",Modifier.padding(8.dp),style=MaterialTheme.typography.labelSmall)
    }}}
    DisposableEffect(display){onDispose{display.view?.removeJavascriptInterface("RovaiTerminal");display.view?.destroy();display.view=null;inputs.close()}}
}
